    [2690]={name="Latched Belt",quality=1,ilvl=5,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'Grape Manifest'. Pick it over the other reward choices. Starts with Milly Osworth in Elwynn Forest. Objective: Bring the Grape Manifest to Brother Neals in Northshire Abbey.",zone="Elwynn Forest",questName="Grape Manifest",lore="Now that my crop is saved, take this Grape Manifest to Brother Neals. He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes."},
    [2691]={name="Outfitter Boots",quality=1,ilvl=5,reqLevel=1,sourceType="quest_reward",instructions="Reward from the quest 'Skirmish at Echo Ridge'. Pick it over the other reward choices. Starts with Marshal McBride in Elwynn Forest. Objective: Kill 12 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.",zone="Elwynn Forest",questName="Skirmish at Echo Ridge",lore="Your previous investigations are proof that the Echo Ridge Mine needs purging. Return to the mine and help clear it of kobolds. Waste no time."},
    [2694]={name="Settler's Leggings",quality=2,ilvl=17,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'Stolen Silver'. Pick it over the other reward choices. Starts with Gazrog in The Barrens. Objective: Bring the Stolen Silver to Gazrog in the Crossroads.",zone="The Barrens",questName="Stolen Silver",lore="You may have killed the raptors, but the silver they stole must be recovered! I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds."},
    [2817]={name="Soft Leather Tunic",quality=2,ilvl=12,reqLevel=6,sourceType="quest_reward",instructions="Reward from the quest 'Protecting the Herd'. Pick it over the other reward choices. Starts with Rudra Amberstill in Dun Morogh. Objective: Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.",zone="Dun Morogh",questName="Protecting the Herd",lore="We heard the cries in the middle of the night. Then this morning, sure enough, the herd was missing two rams. That dastardly beast known as Vagash has been preying on our livelihood."},
