    [7229]={name="Explorer's Vest",quality=2,ilvl=13,reqLevel=7,sourceType="quest_reward",instructions="Reward from the quest 'Bashal'Aran'. Pick it over the other reward choices. Starts with Asterion in Darkshore. Objective: Destroy the Ancient Moonstone Seal at the ancient flame in Ameth'Aran, then return to Asterion in Bashal'Aran.",zone="Darkshore",questName="Bashal'Aran",lore="It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color."},
