    [9598]={name="Sleeping Robes",quality=2,ilvl=10,reqLevel=3,sourceType="quest_reward",instructions="Reward from the quest 'Druid of the Claw'. Pick it over the other reward choices. Starts with Oben Rageclaw in Teldrassil. Objective: Oben Rageclaw wants you to kill his soulless body, and then use the Voodoo Charm.",zone="Teldrassil",questName="Druid of the Claw",lore="After examining this charm, I see now what must be done. Please take it, and do as I ask. You are to explore the deepest areas of the Ban'ethil Barrow Den."},
    [9599]={name="Barkmail Leggings",quality=2,ilvl=10,reqLevel=4,sourceType="quest_reward",instructions="Reward from the quest 'The Relics of Wakening'. Pick it over the other reward choices. Starts with Athridas Bearmantle in Teldrassil. Objective: Retrieve the Relics of Wakening and bring them to Athridas Bearmantle in Dolanaar.",zone="Teldrassil",questName="The Relics of Wakening",lore="Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west. The slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help."},
